{
  "steps": [
    {
      "id": 1,
      "claim": "Einstein’s photoelectric equation gives the maximum kinetic energy of emitted electrons as KE_max = h·ν – φ.",
      "evidence": "Fundamental result of Einstein’s 1905 theory of the photoelectric effect.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The stopping potential V_s satisfies e·V_s = KE_max.",
      "evidence": "By definition, the stopping voltage is the voltage required to reduce the photocurrent to zero, i.e., to cancel the maximum kinetic energy of the electrons.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Combining (1) and (2) gives V_s = (h/e)·ν – φ/e.",
      "evidence": "Algebraic substitution of KE_max from step 1 into the relation of step 2 and solving for V_s.",
      "weight": 0.20,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Introducing the threshold frequency ν₀ = φ/h, the expression becomes V_s = (h/e)(ν – ν₀).",
      "evidence": "Definition of ν₀ and simple rearrangement of the equation in step 3.",
      "weight": 0.15,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "For frequencies ν > ν₀, V_s is a linear function of ν (slope h/e, intercept –φ/e).",
      "evidence": "Equation in step 4 is of the form y = mx + c; linearity holds provided the photon energy exceeds the work function, i.e., ν > ν₀. (Assumes ideal conditions with no space‑charge or contact‑potential complications.)",
      "weight": 0.10,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Option (D) states exactly this linear relationship between stopping potential and frequency above the threshold.",
      "evidence": "Option D: “potential difference necessary to stop the emitted electrons is a linear function of the frequency above the threshold frequency.”",
      "weight": 0.05,
      "depends_on": [5]
    },
    {
      "id": 7,
      "claim": "Options (A), (B), and (C) are inconsistent with the established theory.",
      "evidence": "Work function φ is a material constant, not proportional to frequency or wavelength; photocurrent depends on light intensity, not directly on wavelength.",
      "weight": 0.05,
      "depends_on": [1]
    }
  ],
  "answer": "D",
  "confidence": 0.97,
  "considered": [
    {
      "answer": "C",
      "reason_rejected": "Photocurrent is proportional to light intensity (number of photons), not linearly to wavelength; the experiment varies frequency, not wavelength, for current."
    },
    {
      "answer": "A",
      "reason_rejected": "Work function is an intrinsic property of the metal, independent of the incident light frequency."
    },
    {
      "answer": "B",
      "reason_rejected": "Work function does not vary with wavelength; energy–wavelength relation is inverse, not proportional."
    }
  ]
}
